// =============================================================================
// NÓ: "Consultar World Bank + Analisar" (n8n Code node, modo "Run Once for All Items")
// =============================================================================
// Reimplementação em JavaScript do pipeline Python (src/data_loader.py,
// src/indicators.py, src/analysis.py, src/pipeline.py), para rodar 100%
// dentro do n8n Cloud, sem precisar de nenhum arquivo local ou Python.
//
// Faz, nesta ordem:
//   1. Consulta a API pública do World Bank (mesma fonte do dataset do Kaggle)
//      para os países e indicadores configurados abaixo.
//   2. Monta uma grade completa de anos por país/indicador e faz interpolação
//      linear dos anos faltantes (equivalente a handle_missing_values do Python).
//   3. Calcula agregações, rankings, crescimento (%) e CAGR, e classifica cada
//      série como "evoluiu" / "estagnado" / "regrediu".
//   4. Gera: (a) CSV final consolidado, (b) CSV de crescimento, e (c) um
//      resumo estruturado compacto para enviar à IA (equivalente ao
//      summary_for_ai.json do projeto Python).
//
// Saída: um único item com { finalCsv, growthCsv, summary }.

const INDICATORS = {
  "SE.XPD.TOTL.GD.ZS": "Gasto público em educação (% do PIB)",
  "SE.XPD.TOTL.GB.ZS": "Gasto público em educação (% do gasto público total)",
  "SE.PRM.ENRR": "Matrícula no ensino primário (% bruto)",
  "SE.SEC.ENRR": "Matrícula no ensino secundário (% bruto)",
  "SE.TER.ENRR": "Matrícula no ensino superior (% bruto)",
  "SE.ADT.LITR.ZS": "Taxa de alfabetização de adultos (%)",
};

const COUNTRIES = ["BRA", "USA", "DEU", "JPN", "IND", "CHN", "ZAF", "ARG", "PRT", "NGA"];
const MIN_YEAR = 2010;
const MAX_YEAR = 2022;
const TOP_N = 10;
const STAGNATION_THRESHOLD = 3.0;

// -----------------------------------------------------------------------
// 1) Consulta à API do World Bank
// -----------------------------------------------------------------------
async function fetchIndicator(indicatorCode) {
  const url = `https://api.worldbank.org/v2/country/${COUNTRIES.join(";")}/indicator/${indicatorCode}`;
  const allRecords = [];
  let page = 1;

  while (true) {
    const response = await this.helpers.httpRequest({
      method: "GET",
      url,
      qs: { format: "json", date: `${MIN_YEAR}:${MAX_YEAR}`, per_page: 1000, page },
      json: true,
    });

    if (!response || !Array.isArray(response) || response.length < 2 || !response[1]) break;
    const [meta, records] = response;
    allRecords.push(...records);

    if (page >= (meta.pages || 1)) break;
    page += 1;
  }
  return allRecords;
}

function recordsToRows(records) {
  return records.map((r) => ({
    country_name: r.country.value,
    country_code: r.countryiso3code || r.country.id,
    indicator_code: r.indicator.id,
    year: parseInt(r.date, 10),
    value: r.value === null || r.value === undefined ? null : parseFloat(r.value),
  }));
}

// -----------------------------------------------------------------------
// 2) Grade completa de anos + interpolação linear (tratamento de ausentes)
// -----------------------------------------------------------------------
function interpolateGroup(yearRows) {
  const values = yearRows.map((r) => r.value);
  const known = [];
  for (let i = 0; i < values.length; i++) if (values[i] !== null) known.push(i);
  if (known.length === 0) return yearRows.map((r) => ({ ...r, value: null }));

  for (let i = 0; i < values.length; i++) {
    if (values[i] !== null) continue;
    let prev = null;
    let next = null;
    for (const k of known) {
      if (k < i) prev = k;
      if (k > i && next === null) next = k;
    }
    if (prev !== null && next !== null) {
      const frac = (i - prev) / (next - prev);
      values[i] = values[prev] + (values[next] - values[prev]) * frac;
    } else if (prev !== null) {
      values[i] = values[prev];
    } else if (next !== null) {
      values[i] = values[next];
    }
  }
  return yearRows.map((r, i) => ({ ...r, value: values[i] }));
}

function cleanAndFillMissing(rawRows) {
  // Agrupa por país+indicador
  const groups = {};
  for (const r of rawRows) {
    const key = `${r.country_code}|${r.indicator_code}`;
    if (!groups[key]) {
      groups[key] = { country_name: r.country_name, country_code: r.country_code, indicator_code: r.indicator_code, byYear: {} };
    }
    groups[key].byYear[r.year] = r.value;
  }

  const finalRows = [];
  for (const key of Object.keys(groups)) {
    const g = groups[key];
    const yearRows = [];
    for (let year = MIN_YEAR; year <= MAX_YEAR; year++) {
      yearRows.push({
        country_name: g.country_name,
        country_code: g.country_code,
        indicator_code: g.indicator_code,
        year,
        value: Object.prototype.hasOwnProperty.call(g.byYear, year) ? g.byYear[year] : null,
      });
    }
    const interpolated = interpolateGroup(yearRows);
    const stillMissing = interpolated.some((r) => r.value === null);
    if (stillMissing) continue; // série sem nenhum dado observável - descarta
    finalRows.push(...interpolated);
  }
  return finalRows;
}

// -----------------------------------------------------------------------
// 3) Agregações, rankings, crescimento/CAGR, classificação de tendência
// -----------------------------------------------------------------------
function classifyTrend(pctChange) {
  if (pctChange === null || Number.isNaN(pctChange)) return "indefinido";
  if (pctChange > STAGNATION_THRESHOLD) return "evoluiu";
  if (pctChange < -STAGNATION_THRESHOLD) return "regrediu";
  return "estagnado";
}

function calculateGrowth(rows) {
  const groups = {};
  for (const r of rows) {
    const key = `${r.country_code}|${r.indicator_code}`;
    if (!groups[key]) groups[key] = [];
    groups[key].push(r);
  }

  const results = [];
  for (const key of Object.keys(groups)) {
    const group = groups[key].sort((a, b) => a.year - b.year);
    if (group.length < 2) continue;
    const first = group[0];
    const last = group[group.length - 1];
    const nYears = last.year - first.year;

    const absChange = last.value - first.value;
    const pctChange = first.value !== 0 ? (absChange / first.value) * 100 : null;

    let cagr = null;
    if (nYears > 0 && first.value > 0 && last.value > 0) {
      cagr = (Math.pow(last.value / first.value, 1 / nYears) - 1) * 100;
    }

    results.push({
      country_name: first.country_name,
      country_code: first.country_code,
      indicator_code: first.indicator_code,
      first_year: first.year,
      last_year: last.year,
      first_value: Math.round(first.value * 100) / 100,
      last_value: Math.round(last.value * 100) / 100,
      abs_change: Math.round(absChange * 100) / 100,
      pct_change: pctChange !== null ? Math.round(pctChange * 100) / 100 : null,
      cagr_pct: cagr !== null ? Math.round(cagr * 100) / 100 : null,
      trend: classifyTrend(pctChange),
    });
  }
  return results;
}

function aggregateByCountryIndicator(rows) {
  const groups = {};
  for (const r of rows) {
    const key = `${r.country_code}|${r.indicator_code}`;
    if (!groups[key]) groups[key] = { country_name: r.country_name, country_code: r.country_code, indicator_code: r.indicator_code, values: [] };
    groups[key].values.push(r.value);
  }
  return Object.values(groups).map((g) => {
    const mean = g.values.reduce((a, b) => a + b, 0) / g.values.length;
    return {
      country_name: g.country_name,
      country_code: g.country_code,
      indicator_code: g.indicator_code,
      mean_value: Math.round(mean * 100) / 100,
      min_value: Math.round(Math.min(...g.values) * 100) / 100,
      max_value: Math.round(Math.max(...g.values) * 100) / 100,
    };
  });
}

function rankCountriesByIndicator(rows, indicatorCode, topN = TOP_N) {
  const subset = rows.filter((r) => r.indicator_code === indicatorCode);
  const latestByCountry = {};
  for (const r of subset) {
    const key = r.country_code;
    if (!latestByCountry[key] || r.year > latestByCountry[key].year) latestByCountry[key] = r;
  }
  const ranked = Object.values(latestByCountry).sort((a, b) => b.value - a.value);
  return ranked.slice(0, topN).map((r, i) => ({
    rank: i + 1,
    country_name: r.country_name,
    country_code: r.country_code,
    year: r.year,
    value: r.value,
  }));
}

// -----------------------------------------------------------------------
// 4) CSV helper
// -----------------------------------------------------------------------
function toCsv(rows, columns) {
  const header = columns.join(",");
  const lines = rows.map((r) =>
    columns
      .map((c) => {
        const v = r[c] === null || r[c] === undefined ? "" : r[c];
        const s = String(v);
        return s.includes(",") ? `"${s}"` : s;
      })
      .join(",")
  );
  return [header, ...lines].join("\n");
}

// -----------------------------------------------------------------------
// Execução principal
// -----------------------------------------------------------------------
let rawRows = [];
const failedIndicators = [];

for (const indicatorCode of Object.keys(INDICATORS)) {
  try {
    const records = await fetchIndicator.call(this, indicatorCode);
    rawRows.push(...recordsToRows(records));
  } catch (err) {
    failedIndicators.push(indicatorCode);
  }
}

if (rawRows.length === 0) {
  throw new Error(
    "Nenhum dado retornado pela API do World Bank para nenhum indicador. Verifique conectividade do n8n Cloud."
  );
}

const cleanedRows = cleanAndFillMissing(rawRows);
const growth = calculateGrowth(cleanedRows);
const aggregation = aggregateByCountryIndicator(cleanedRows);

const rankings = {};
for (const indicatorCode of Object.keys(INDICATORS)) {
  rankings[indicatorCode] = rankCountriesByIndicator(cleanedRows, indicatorCode);
}

const topGrowth = [...growth].sort((a, b) => (b.pct_change ?? -Infinity) - (a.pct_change ?? -Infinity)).slice(0, TOP_N);
const topDecline = [...growth].sort((a, b) => (a.pct_change ?? Infinity) - (b.pct_change ?? Infinity)).slice(0, TOP_N);
const stagnant = growth.filter((g) => g.trend === "estagnado").slice(0, TOP_N);
const topInvestment = aggregation
  .filter((a) => a.indicator_code === "SE.XPD.TOTL.GD.ZS")
  .sort((a, b) => b.mean_value - a.mean_value)
  .slice(0, TOP_N)
  .map((a) => ({ country_name: a.country_name, mean_value: a.mean_value }));

const summary = {
  period_covered: { min_year: MIN_YEAR, max_year: MAX_YEAR },
  countries_analyzed: [...new Set(cleanedRows.map((r) => r.country_name))].sort(),
  indicators_analyzed: Object.keys(INDICATORS),
  indicators_failed: failedIndicators,
  top_growth: topGrowth,
  top_decline: topDecline,
  stagnant_examples: stagnant,
  top_investment_pct_gdp: topInvestment,
  rankings_by_indicator: rankings,
};

const finalCsv = toCsv(cleanedRows, ["country_name", "country_code", "indicator_code", "year", "value"]);
const growthCsv = toCsv(growth, [
  "country_name",
  "country_code",
  "indicator_code",
  "first_year",
  "last_year",
  "first_value",
  "last_value",
  "abs_change",
  "pct_change",
  "cagr_pct",
  "trend",
]);

return [{ json: { summary, finalCsv, growthCsv } }];

// =============================================================================
// NÓ: "Montar Prompt para a IA" (n8n Code node, modo "Run Once for All Items")
// =============================================================================
// Recebe o item vindo do nó anterior ("Consultar World Bank + Analisar"),
// que contém $json.summary, e monta o corpo da requisição para a API do
// Claude (mesmo prompt usado em src/ai_report.py e prompts/executive_report_prompt.md).

const summary = $input.first().json.summary;

const systemPrompt = `Você é um analista sênior de políticas educacionais internacionais, atuando para um organismo multilateral. Sua função é interpretar indicadores educacionais de diferentes países e produzir inteligência acionável para tomadores de decisão — não apenas descrever números.

Regras obrigatórias:
- Nunca apenas repita ou resuma os números recebidos; sempre acrescente interpretação, hipóteses causais plausíveis e implicações práticas.
- Identifique explicitamente: países que mais evoluíram, países estagnados ou em regressão, países com maior investimento relativo, países com melhores indicadores absolutos.
- Para cada padrão identificado, proponha possíveis explicações (ex: crises econômicas, reformas educacionais, mudanças demográficas) deixando claro quando é hipótese e não fato comprovado pelos dados.
- Termine com recomendações concretas e priorizadas.
- Seja direto, use linguagem executiva, evite jargão técnico desnecessário.`;

const userPrompt = `Abaixo está um resumo estruturado (JSON) com indicadores educacionais de múltiplos países, já processados (rankings, crescimento, agregações).

Gere um RELATÓRIO EXECUTIVO em Markdown com as seções:

1. Panorama geral (2-3 parágrafos)
2. Países em destaque (maior evolução, com hipóteses do porquê)
3. Países estagnados ou em regressão (com hipóteses do porquê)
4. Investimento vs. resultado (quem investe mais e o retorno aparente)
5. Melhores indicadores absolutos (não confundir com crescimento: quais países têm hoje os melhores números em termos absolutos em cada indicador, usando os rankings fornecidos)
6. Comparações relevantes entre países
7. Recomendações (priorizadas, acionáveis)

Dados:
\`\`\`json
${JSON.stringify(summary, null, 2)}
\`\`\``;

return [
  {
    json: {
      model: "claude-sonnet-4-6",
      max_tokens: 4000,
      system: systemPrompt,
      messages: [{ role: "user", content: userPrompt }],
    },
  },
];

// =============================================================================
// NÓ: "Extrair Relatório da Resposta" (n8n Code node, modo "Run Once for All Items")
// =============================================================================
// Recebe a resposta bruta da API do Claude (nó HTTP Request anterior) e
// extrai o texto do relatório em Markdown, pronto para ser salvo.

const response = $input.first().json;
const textBlocks = (response.content || []).filter((b) => b.type === "text");
const reportText = textBlocks.map((b) => b.text).join("\n");

const now = new Date();
const timestamp = now.toISOString().slice(0, 10);
const header = `# Relatório Executivo - Indicadores Educacionais\n\n_Gerado automaticamente em ${timestamp} via n8n Cloud_\n\n---\n\n`;

return [
  {
    json: {
      fileName: `executive_report_${timestamp}.md`,
      content: header + reportText,
    },
  },
];

// =============================================================================
// NÓ: "Montar Relatório HTML com Gráficos" (n8n Code node, "Run Once for All Items")
// =============================================================================
// Versão com gráficos em PNG DE VERDADE (via QuickChart.io, serviço gratuito,
// sem necessidade de conta/chave para este uso), em vez de SVG.
//
// Motivo da troca: a maioria dos clientes de e-mail (Gmail incluso) NÃO
// renderiza <svg> dentro do corpo do e-mail, por restrição de segurança.
// PNG funciona em qualquer lugar. Os gráficos são gerados chamando a API
// pública do QuickChart (POST /chart/create), que devolve uma URL de
// imagem estável — essa URL é embutida como <img src="...">.
//
// Recebe o texto em Markdown gerado pela IA (nó anterior: "Extrair Relatório
// da Resposta") e o resumo estruturado original (nó "Consultar World Bank +
// Analisar", acessado por referência cruzada via $()).
//
// Saída: { fileName, htmlContent } pronto para: (a) enviar por e-mail como
// corpo HTML, e/ou (b) salvar/anexar como arquivo .html.

const COLOR_GROWTH = "#2E7D32";
const COLOR_DECLINE = "#C62828";
const COLOR_ACCENT = "#1565C0";
const COLOR_GOLD = "#B8860B";

// ---- 1) Cria um gráfico no QuickChart e devolve a URL da imagem ----
async function createChartUrl(chartConfig, width, height) {
  try {
    const response = await this.helpers.httpRequest({
      method: "POST",
      url: "https://quickchart.io/chart/create",
      body: {
        chart: chartConfig,
        width,
        height,
        backgroundColor: "white",
        devicePixelRatio: 2.0,
      },
      json: true,
    });
    if (response && response.success && response.url) {
      return response.url;
    }
  } catch (err) {
    // Se o QuickChart falhar (indisponível, rate limit, etc.), o relatório
    // ainda deve ser gerado - só sem esse gráfico específico.
  }
  return null;
}

async function barChartImg(title, items, labelKey, valueKey, color, xLabel) {
  if (!items || items.length === 0) {
    return `<p><em>Sem dados suficientes para o gráfico "${title}".</em></p>`;
  }
  const config = {
    type: "horizontalBar",
    data: {
      labels: items.map((i) => String(i[labelKey]).slice(0, 20)),
      datasets: [
        {
          label: xLabel || title,
          data: items.map((i) => i[valueKey] ?? 0),
          backgroundColor: items.map((i) => (i[valueKey] >= 0 ? color : COLOR_DECLINE)),
        },
      ],
    },
    options: {
      title: { display: true, text: title, fontSize: 16 },
      legend: { display: false },
      scales: {
        xAxes: [{ scaleLabel: { display: !!xLabel, labelString: xLabel } }],
      },
    },
  };
  const height = Math.max(220, items.length * 42 + 60);
  const url = await createChartUrl.call(this, config, 600, height);
  if (!url) {
    return `<p><em>Gráfico "${title}" temporariamente indisponível.</em></p>`;
  }
  return `<img src="${url}" alt="${title}" style="max-width:100%;border-radius:8px;display:block;margin:0 auto;" />`;
}

async function scatterChartImg(title, points, xLabel, yLabel) {
  if (!points || points.length === 0) {
    return `<p><em>Sem dados suficientes para o gráfico "${title}".</em></p>`;
  }
  const config = {
    type: "scatter",
    data: {
      datasets: [
        {
          label: title,
          data: points.map((p) => ({ x: p.x, y: p.y })),
          backgroundColor: COLOR_ACCENT,
          pointRadius: 6,
        },
      ],
    },
    options: {
      title: { display: true, text: title, fontSize: 16 },
      legend: { display: false },
      scales: {
        xAxes: [{ scaleLabel: { display: true, labelString: xLabel } }],
        yAxes: [{ scaleLabel: { display: true, labelString: yLabel } }],
      },
    },
  };
  const url = await createChartUrl.call(this, config, 520, 380);
  const imgHtml = url
    ? `<img src="${url}" alt="${title}" style="max-width:100%;border-radius:8px;display:block;margin:0 auto;" />`
    : `<p><em>Gráfico "${title}" temporariamente indisponível.</em></p>`;

  // QuickChart (config simples acima) não rotula cada ponto com o nome do
  // país - por isso, incluímos uma legenda em tabela HTML logo abaixo, para
  // não perder essa informação mesmo se o gráfico não rotular os pontos.
  const legendRows = points
    .map((p) => `<tr><td>${p.label}</td><td>${p.x}</td><td>${p.y}</td></tr>`)
    .join("");
  const legendTable = `
    <table style="width:100%; font-size:12px; margin-top:8px; border-collapse:collapse;">
      <tr style="background:#F1F8F2;"><th style="text-align:left;padding:4px 8px;">País</th><th style="text-align:left;padding:4px 8px;">${xLabel}</th><th style="text-align:left;padding:4px 8px;">${yLabel}</th></tr>
      ${legendRows}
    </table>`;

  return imgHtml + legendTable;
}

// ---- 2) Conversor simples de Markdown para HTML ----
function markdownToHtml(md) {
  const lines = md.split("\n");
  let html = "";
  let inList = false;

  for (const rawLine of lines) {
    const line = rawLine.trim();

    if (line === "") {
      if (inList) {
        html += "</ul>\n";
        inList = false;
      }
      continue;
    }

    const headerMatch = line.match(/^(#{1,3})\s+(.*)/);
    if (headerMatch) {
      if (inList) {
        html += "</ul>\n";
        inList = false;
      }
      const level = headerMatch[1].length + 1;
      html += `<h${level}>${inlineFormat(headerMatch[2])}</h${level}>\n`;
      continue;
    }

    const listMatch = line.match(/^[-*]\s+(.*)/);
    if (listMatch) {
      if (!inList) {
        html += "<ul>\n";
        inList = true;
      }
      html += `<li>${inlineFormat(listMatch[1])}</li>\n`;
      continue;
    }

    if (line === "---") {
      if (inList) {
        html += "</ul>\n";
        inList = false;
      }
      html += "<hr/>\n";
      continue;
    }

    if (inList) {
      html += "</ul>\n";
      inList = false;
    }
    html += `<p>${inlineFormat(line)}</p>\n`;
  }
  if (inList) html += "</ul>\n";
  return html;
}

function inlineFormat(text) {
  return text.replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>").replace(/\*(.+?)\*/g, "<em>$1</em>");
}

// ---- 3) Cartões de KPI ----
function kpiCardsHtml(summary) {
  const period = summary.period_covered;
  const nCountries = summary.countries_analyzed.length;
  const topGrower = summary.top_growth && summary.top_growth[0];
  const topDecliner = summary.top_decline && summary.top_decline[0];
  const topInvestor = summary.top_investment_pct_gdp && summary.top_investment_pct_gdp[0];

  const card = (label, value, sub, color) => `
    <div class="kpi-card">
      <div class="kpi-label">${label}</div>
      <div class="kpi-value" style="color:${color}">${value}</div>
      <div class="kpi-sub">${sub}</div>
    </div>`;

  let html = card("Período analisado", `${period.min_year}–${period.max_year}`, `${nCountries} países`, "#333");
  if (topGrower) {
    html += card("Maior crescimento", `+${topGrower.pct_change}%`, `${topGrower.country_name} (${topGrower.indicator_code})`, COLOR_GROWTH);
  }
  if (topDecliner) {
    html += card("Maior queda", `${topDecliner.pct_change}%`, `${topDecliner.country_name} (${topDecliner.indicator_code})`, COLOR_DECLINE);
  }
  if (topInvestor) {
    html += card("Maior investimento (% PIB)", `${topInvestor.mean_value}%`, topInvestor.country_name, COLOR_GOLD);
  }
  return `<div class="kpi-grid">${html}</div>`;
}

// ---- 4) Junta dois rankings pelo country_code (para o gráfico de dispersão) ----
function joinRankings(summary, indicatorX, indicatorY) {
  const rankX = {};
  (summary.rankings_by_indicator[indicatorX] || []).forEach((r) => (rankX[r.country_code] = r));
  const rankY = {};
  (summary.rankings_by_indicator[indicatorY] || []).forEach((r) => (rankY[r.country_code] = r));

  const commonCodes = Object.keys(rankX).filter((c) => rankY[c]);
  return commonCodes.map((c) => ({
    label: rankX[c].country_name,
    x: rankX[c].value,
    y: rankY[c].value,
  }));
}

// ---- 5) Montagem do documento final ----
const reportItem = $input.first().json; // { fileName, content } vindo do nó anterior
const summary = $("Consultar World Bank + Analisar").item.json.summary;

const kpiHtml = kpiCardsHtml(summary);

const growthChart = await barChartImg.call(
  this,
  "Maior crescimento no período (%)",
  summary.top_growth.slice(0, 8),
  "country_name",
  "pct_change",
  COLOR_GROWTH,
  "% de variação"
);
const declineChart = await barChartImg.call(
