);

const absoluteIndicator = summary.rankings_by_indicator["SE.TER.ENRR"]
  ? "SE.TER.ENRR"
  : Object.keys(summary.rankings_by_indicator)[0];
const absoluteChart = absoluteIndicator
  ? await barChartImg.call(
