      summary.rankings_by_indicator[absoluteIndicator].slice(0, 8),
      "country_name",
      "value",
      COLOR_ACCENT,
      "Valor do indicador"
    )
  : "";

let scatterChart = "";
if (summary.rankings_by_indicator["SE.XPD.TOTL.GD.ZS"] && summary.rankings_by_indicator["SE.TER.ENRR"]) {
  const points = joinRankings(summary, "SE.XPD.TOTL.GD.ZS", "SE.TER.ENRR");
