// NÓ: "Preparar Anexo do Relatório" (n8n Code node, "Run Once for All Items")
// =============================================================================
// O nó do Gmail (e o de e-mail em geral) só consegue anexar ARQUIVOS
// BINÁRIOS, não texto puro. Este nó pega o HTML já pronto (campo
// htmlContent, vindo do nó "Montar Relatório HTML com Gráficos") e usa o
// helper nativo do n8n para transformá-lo num anexo binário de verdade,
// mantendo também os campos originais (json) para uso no corpo do e-mail.

const item = $input.first().json;

const buffer = Buffer.from(item.htmlContent, "utf-8");
const binaryData = await this.helpers.prepareBinaryData(buffer, item.fileName, "text/html");

return [
  {
    json: item, // mantém fileName e htmlContent disponíveis para o nó do Gmail
    binary: {
      report: binaryData, // nome usado no campo "Input Data Field Name" do anexo, no Gmail
    },
  },
];
